/*!40000 ALTER TABLE `disease` DISABLE KEYS */;
INSERT INTO `disease` VALUES (1,'健康猪只','健康,正常',NULL,'无呼吸道疾病的正常猪只','呼吸平稳，无咳嗽，精神饱满','normal',1,'2026-08-13 19:33:43'),(2,'猪流行性感冒','猪流感,SI,Swine Influenza',NULL,'流感病毒引起的急性呼吸道病','鹅鸣样剧咳，突发高热，全群发病','influenza',1,'2026-08-13 19:33:43'),(3,'猪蓝耳病','蓝耳病,猪蓝耳病,PRRS,猪繁殖与呼吸障碍综合征,神秘猪病,HP-PRRS','猪繁殖与呼吸综合征病毒（PRRSV）','动脉炎病毒科RNA病毒，免疫抑制性强（\"免疫抑制之王\"），猪唯一易感；妊娠母猪和1月龄内仔猪最易感，哺乳仔猪死亡率可达80%以上；接触/气溶胶/精液/垂直四种传播途径；冬春高发','繁殖障碍+呼吸道症状，\"三高一低\"（高体温/高发病率/高死亡率/低治愈率）：母猪发热40-42.5℃、妊娠后期流产早产死胎木乃伊胎、耳尖及躯干发绀；仔猪呼吸困难、耳尖发紫继而全耳蓝紫色、共济失调、僵猪比例大；育肥猪两耳发蓝、生长发育缓慢；剖检间质性肺炎\"橡皮肺\"','prrs',13,'2026-08-13 19:33:43'),(4,'猪支原体肺炎','猪气喘病,支原体肺炎,Mhp',NULL,'猪肺炎支原体引起的慢性呼吸道病','慢性干咳，早晚加重，病程长','mycoplasma',1,'2026-08-13 19:33:43'),(5,'猪传染性胸膜肺炎','APP,胸膜肺炎放线杆菌病',NULL,'胸膜肺炎放线杆菌引起','急骤痛咳，湿咳，全身重症，高致死率','app',13,'2026-08-13 19:33:43'),(7,'猪肺疫','猪巴氏杆菌病,锁喉风,肿脖子瘟,Pasteurella multocida','多杀性巴氏杆菌','急性败血症、死亡快','咳嗽、呼吸困难、颈部肿胀','pasteurella',1,'2026-08-14 16:29:17'),(8,'混合感染','PRDC,多病原混合感染','多种病原','病程长、反复发作','咳嗽、喘促、精神萎靡','mixed',1,'2026-08-14 16:29:17');
/*!40000 ALTER TABLE `disease` ENABLE KEYS */;
UNLOCK TABLES;

