DROP TABLE IF EXISTS `farmer_guidance`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `farmer_guidance` (
  `guidance_id` int NOT NULL AUTO_INCREMENT,
  `group_id` int NOT NULL COMMENT '猪群ID',
  `feedback_id` int DEFAULT NULL COMMENT '基于的反馈ID（关联treatment_feedback）',
  `prescription_id` bigint unsigned DEFAULT NULL COMMENT '关联处方ID（关联prescription_record）',
  `guidance_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `guidance_type` enum('初诊建议','增减用量','换方','停药','加强护理','紧急处理') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '指导类型',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '指导正文(自然语言)',
  `suggested_adjustments` json DEFAULT NULL COMMENT '建议调整: [{"herb_name":"麻黄","change":"+3g","reason":"..."}]',
  `urgency_level` enum('普通','紧急') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '普通',
  `is_executed` tinyint(1) DEFAULT '0' COMMENT '农户是否已执行',
  `executed_time` datetime DEFAULT NULL COMMENT '执行时间',
  `executed_result` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '执行结果描述',
  `generated_by` enum('AI','兽医','系统') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'AI',
  `agent_version` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '生成Agent版本',
  PRIMARY KEY (`guidance_id`) USING BTREE,
  KEY `group_id` (`group_id`) USING BTREE,
  CONSTRAINT `farmer_guidance_ibfk_1` FOREIGN KEY (`group_id`) REFERENCES `pig_groups` (`group_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='农户指导建议表';
